usage.example:
export function HistoryTab() {
    const { entries } = useHistory();

    return (
        <FlatList
            data={entries}
            renderItem={({ item }) => (
                <Text>{item.mealType} on {item.date}</Text>
            )}
        />
    );
}

function.example:
const { items, addItem, toggleItem } = useGroceries();

const handleAdd = () => {
    addItem({
        id: `${Date.now()}_${Math.random()}`,
        name: "Milk",
        quantity: 1,
        unit: "liter",
        checked: false
    });
};
